import java.util.*; public class Solution { public List<String> wordBreak(String s, List<String> wordDict) { Map<String, List<String>> memo = new HashMap<>(); Set<String> dict = new HashSet<>(wordDict); return backtrack(s, dict, memo); } private List<String> backtrack(String s, Set<String> dict, Map<String, List<String>> memo) { if (memo.containsKey(s)) return memo.get(s); List<String> result = new ArrayList<>(); if (s.isEmpty()) { result.add(""); return result; } for (int i = 1; i <= s.length(); i++) { String prefix = s.substring(0, i); if (dict.contains(prefix)) { List<String> suffixes = backtrack(s.substring(i), dict, memo); for (String suffix : suffixes) { result.add(prefix + (suffix.isEmpty() ? "" : " ") + suffix); } } } memo.put(s, result); return result; } }